package org.springframework.samples.petclinic.model;

import java.time.LocalDate;
import java.time.Month;

/**
 * The single definition of the <em>fiscal year</em> a date falls in, where the fiscal year starts
 * on 1 July and is named by the calendar year it ends in — so 1 July 2025 to 30 June 2026 is fiscal
 * year 2026, labelled {@code FY26}.
 *
 * <p>Used by the response mapper to derive an owner's {@code fiscalYear} label and the year segment
 * of their membership number, and by {@link Tenure} to count elapsed fiscal years — all from the
 * business-day-adjusted registration date stamped on the owner at creation.
 */
public final class FiscalYear {

    /** The month a fiscal year starts on. */
    private static final Month START = Month.JULY;

    private FiscalYear() {
    }

    /** The fiscal year (named by the calendar year it ends in) that contains {@code date}. */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
    }

    /** The {@code FY<YY>} label for the fiscal year containing {@code date}, where YY is the last
     * two digits of the fiscal year, or null when the date is unknown. */
    public static String label(LocalDate date) {
        return date == null ? null : String.format("FY%02d", of(date) % 100);
    }
}

package org.springframework.samples.petclinic.rest.audit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Immutable structured audit event recorded when an owner is created, serialized to JSON on the
 * {@code AUDIT} logger so downstream systems have a machine-readable trail alongside the
 * human-readable audit line.
 *
 * <p>{@code customerCode} is the owner's <em>current</em> primary identifier. {@link #of} is the
 * single place that decides which identifier the event carries: when the customer code is later
 * unified into a member id, only this factory (and the field name) change, and every emitted
 * event follows.
 *
 * @param seq             monotonically increasing sequence number across creates
 * @param ownerId         the created owner's id
 * @param customerCode    the owner's current primary identifier
 * @param membershipLevel the owner's derived membership level (1-4)
 * @param event           the event marker, always {@link #OWNER_CREATED}
 */
public record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel, String event) {

    /** The event marker distinguishing an owner-created event in the audit stream. */
    public static final String OWNER_CREATED = "OWNER_CREATED";

    /**
     * The owner-created event for {@code owner}, carrying its current primary identifier.
     *
     * @param seq             the sequence number for this event
     * @param owner           the just-saved owner (its id is already assigned)
     * @param membershipLevel the owner's derived membership level
     * @return the immutable event
     */
    public static OwnerCreatedEvent of(long seq, Owner owner, int membershipLevel) {
        return new OwnerCreatedEvent(seq, owner.getId(), owner.getCustomerCode(), membershipLevel, OWNER_CREATED);
    }
}

