3	import java.util.Locale;
4	
5	/**
6	 * The single definition of an owner's <em>identity key</em>: the SHA-256 fingerprint that
7	 * decides when two owners are the same person. It is the full 64-character lower-case hex
8	 * digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, and is
9	 * both returned on the owner response and used by the create pipeline to reject a duplicate.
10	 */
11	public final class OwnerIdentity {
12	
13	    private OwnerIdentity() {
14	    }
15	
16	    /**
17	     * The identity key for the given fields: the lower-case hex SHA-256 of
18	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone
19	     * is expected already normalized (E.164) by the create pipeline; the email is lower-cased
20	     * and the last name reduced to its {@link Soundex} code here, so callers may pass the raw
21	     * stored values. A null telephone or email contributes an empty string.
22	     */
23	    public static String key(String telephone, String email, String lastName) {
24	        String raw = part(telephone) + '|' + lower(email) + '|' + Soundex.encode(lastName);
25	        return Sha256.lowerHex(raw);
26	    }
27	
28	    /** The identity key of a stored owner, derived from its telephone, email and last name. */
29	    public static String of(Owner owner) {
30	        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
31	    }
32	
33	    private static String part(String value) {
34	        return value == null ? "" : value;
35	    }
36	
37	    private static String lower(String value) {
38	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
39	    }
40	}
