1	package org.springframework.samples.petclinic.model;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * The single definition of a SHA-256 fingerprint of a string. Shared by everything that
9	 * fingerprints owner data — the customer code hash and household id (a truncated upper-case
10	 * prefix) and the identity key (the full lower-case digest) — so they all hash identically.
11	 */
12	public final class Sha256 {
13	
14	    private Sha256() {
15	    }
16	
17	    /**
18	     * The first {@code length} upper-case hex characters of SHA-256 over the UTF-8 bytes of
19	     * {@code value}.
20	     *
21	     * @param value  the string to hash
22	     * @param length the number of leading hex characters to return
23	     * @return the truncated upper-case hex digest
24	     */
25	    public static String upperHex(String value, int length) {
26	        return hex(value, "%02X").substring(0, length);
27	    }
28	
29	    /**
30	     * The full 64-character lower-case hex SHA-256 over the UTF-8 bytes of {@code value}.
31	     *
32	     * @param value the string to hash
33	     * @return the complete lower-case hex digest
34	     */
35	    public static String lowerHex(String value) {
36	        return hex(value, "%02x");
37	    }
38	
39	    private static String hex(String value, String byteFormat) {
40	        try {
41	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
42	            StringBuilder hex = new StringBuilder(digest.length * 2);
43	            for (byte b : digest) {
44	                hex.append(String.format(byteFormat, b & 0xFF));
45	            }
46	            return hex.toString();
47	        } catch (NoSuchAlgorithmException ex) {
48	            throw new IllegalStateException("SHA-256 is required to derive a fingerprint", ex);
49	        }
50	    }
51	}
