1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * The single definition of the <em>fiscal year</em> a date falls in, where the fiscal year starts
8	 * on 1 July and is named by the calendar year it ends in — so 1 July 2025 to 30 June 2026 is fiscal
9	 * year 2026, labelled {@code FY26}.
10	 *
11	 * <p>Used by the response mapper to derive an owner's {@code fiscalYear} label and the year segment
12	 * of their membership number, and by {@link Tenure} to count elapsed fiscal years — all from the
13	 * business-day-adjusted registration date stamped on the owner at creation.
14	 */
15	public final class FiscalYear {
16	
17	    /** The month a fiscal year starts on. */
18	    private static final Month START = Month.JULY;
19	
20	    private FiscalYear() {
21	    }
22	
23	    /** The fiscal year (named by the calendar year it ends in) that contains {@code date}. */
24	    public static int of(LocalDate date) {
25	        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /** The {@code FY<YY>} label for the fiscal year containing {@code date}, where YY is the last
29	     * two digits of the fiscal year, or null when the date is unknown. */
30	    public static String label(LocalDate date) {
31	        return date == null ? null : String.format("FY%02d", of(date) % 100);
32	    }
33	}
