1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.CheckDigit;
9	import org.springframework.samples.petclinic.model.CustomerCode;
10	import org.springframework.samples.petclinic.model.FiscalYear;
11	import org.springframework.samples.petclinic.model.Locality;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.model.OwnerIdentity;
14	import org.springframework.samples.petclinic.model.OwnerSegment;
15	import org.springframework.samples.petclinic.model.Tenure;
16	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
17	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
18	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
19	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones;
20	
21	import java.util.Collection;
22	import java.util.List;
23	
24	/**
25	 * Maps Owner & OwnerDto using Mapstruct
26	 */
27	@Mapper(uses = PetMapper.class)
28	public interface OwnerMapper {
29	
30	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
31	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
32	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
33	    @Mapping(target = "initials", expression = "java(initials(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
35	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
38	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
42	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
43	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
44	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
45	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
46	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    @Mapping(target = "membershipLevelCap", ignore = true)
50	    Owner toOwner(OwnerDto ownerDto);
51	
52	    /** The owner's canonical API path: '/api/owners/' followed by the owner's id. */
53	    default String selfLink(Owner owner) {
54	        return "/api/owners/" + owner.getId();
55	    }
56	
57	    /** The owner's salutation: '&lt;title&gt; &lt;lastName&gt;' when a title was supplied,
58	     * otherwise just the last name. */
59	    default String salutation(Owner owner) {
60	        String title = owner.getTitle();
61	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
62	    }
63	
64	    /** Format an owner's name as 'LastName, FirstName' for display. */
65	    default String displayName(Owner owner) {
66	        return owner.getLastName() + ", " + owner.getFirstName();
67	    }
68	
69	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
70	    default String initials(Owner owner) {
71	        return initial(owner.getFirstName()) + initial(owner.getLastName());
72	    }
73	
74	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
75	    default String telephoneDisplay(Owner owner) {
76	        return OwnerTelephones.toDisplay(owner.getTelephone());
77	    }
78	
79	    private static String initial(String name) {
80	        return Character.toUpperCase(name.charAt(0)) + ".";
81	    }
82	
83	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
84	     * last two digits of the fiscal year of the registrationDate (see {@link FiscalYear}). */
85	    default String membershipNumber(Owner owner) {
86	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
87	            return null;
88	        }
89	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
90	    }
91	
92	    /** The owner's 'FY&lt;YY&gt;' fiscal year, derived from the business-day-adjusted
93	     * registrationDate (see {@link FiscalYear}), or null when the date is unknown. */
94	    default String fiscalYear(Owner owner) {
95	        return FiscalYear.label(owner.getRegistrationDate());
96	    }
97	
98	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
99	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure is at least one
100	     * elapsed fiscal year. */
101	    default int membershipPoints(Owner owner) {
102	        int points = 0;
103	        if (hasEmail(owner)) {
104	            points += 2;
105	        }
106	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
107	            points += 1;
108	        }
109	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
110	            points += 2;
111	        }
112	        if (Tenure.fiscalYears(owner.getRegistrationDate()) >= 1) {
113	            points += 3;
114	        }
115	        return points;
116	    }
117	
118	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
119	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. When the owner carries a
120	     * {@code membershipLevelCap} (set at creation from their household; see
121	     * {@code AssignOwnerMembershipLevelCap}) the derived level is clamped to that ceiling. */
122	    default int membershipLevel(Owner owner) {
123	        int points = membershipPoints(owner);
124	        int level;
125	        if (points <= 1) {
126	            level = 1;
127	        } else if (points <= 3) {
128	            level = 2;
129	        } else if (points <= 5) {
130	            level = 3;
131	        } else {
132	            level = 4;
133	        }
134	        Integer cap = owner.getMembershipLevelCap();
135	        return cap == null ? level : Math.min(level, cap);
136	    }
137	
138	    /** The owner's canonical region: the REGION segment of the customer code (see
139	     * {@link CustomerCode}), or null when the customer code is unset. */
140	    default String locality(Owner owner) {
141	        return CustomerCode.region(owner.getCustomerCode());
142	    }
143	
144	    /** The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;', derived from the owner's
145	     * {@link #membershipLevel(Owner)} and {@link #locality(Owner)} (see {@link OwnerSegment}). */
146	    default String ownerSegment(Owner owner) {
147	        return OwnerSegment.of(membershipLevel(owner), locality(owner));
148	    }
149	
150	    /** The owner's IANA timezone, derived from the locality/region via the pinned
151	     * region-to-timezone table (see {@link Locality#timezoneForRegion}), or null when the
152	     * region is not in the table. */
153	    default String timezone(Owner owner) {
154	        return Locality.timezoneForRegion(locality(owner));
155	    }
156	
157	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
158	    default String contactPreference(Owner owner) {
159	        return hasEmail(owner) ? "EMAIL" : "PHONE";
160	    }
161	
162	    /** Whether the owner has a non-blank email. */
163	    private static boolean hasEmail(Owner owner) {
164	        return owner.getEmail() != null && !owner.getEmail().isBlank();
165	    }
166	
167	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
168	    default String identityKey(Owner owner) {
169	        return OwnerIdentity.of(owner);
170	    }
171	
172	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
