3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Pinned locality reference data. A region is derived from a postcode range
8	 * ({@link #regionForPostcode}) or from the city-to-region table ({@link #regionFor(String)});
9	 * anything unrecognised resolves to {@link #UNKNOWN}.
10	 */
11	public final class Locality {
12	
13	    /** The locality returned for a city that is not in the table. */
14	    public static final String UNKNOWN = "UNKNOWN";
15	
16	    /** A well-formed 4-digit postcode. */
17	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
18	
19	    /** City -> canonical region. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	            "Sydney", "NSW",
22	            "Melbourne", "VIC",
23	            "Brisbane", "QLD");
24	
25	    /** Region -> inclusive 4-digit postcode range {low, high}. */
26	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
27	            "NSW", new int[] {2000, 2099},
28	            "VIC", new int[] {3000, 3099},
29	            "QLD", new int[] {4000, 4099});
30	
31	    /** Region -> IANA timezone name. */
32	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
33	            "NSW", "Australia/Sydney",
34	            "VIC", "Australia/Melbourne",
35	            "QLD", "Australia/Brisbane");
36	
37	    private Locality() {
38	    }
39	
40	    /**
41	     * Derive the canonical region for the given city.
42	     *
43	     * @param city the owner's city (may be {@code null})
44	     * @return the canonical region string, or {@link #UNKNOWN} when the city is not in the table
45	     */
46	    public static String regionFor(String city) {
47	        return CITY_REGION.getOrDefault(city, UNKNOWN);
48	    }
49	
50	    /**
51	     * Derive the canonical region from the postcode alone: the region whose pinned range
52	     * contains it.
53	     *
54	     * @param postcode the owner's postcode (may be {@code null} or non-numeric)
55	     * @return the matching region, or {@link #UNKNOWN} when the postcode is absent, non-numeric or in no range
56	     */
57	    public static String regionForPostcode(String postcode) {
58	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
59	            return UNKNOWN;
60	        }
61	        int value = Integer.parseInt(postcode);
62	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return UNKNOWN;
69	    }
70	
71	    /**
72	     * Whether the given region is one of the pinned known regions (NSW, VIC or QLD).
73	     *
74	     * @param region the canonical region (may be {@code null} or {@link #UNKNOWN})
75	     * @return {@code true} when the region is in the pinned reference data
76	     */
77	    public static boolean isKnownRegion(String region) {
78	        return REGION_POSTCODES.containsKey(region);
79	    }
80	
81	    /**
82	     * The IANA timezone name for the given region, via the pinned region-to-timezone table.
83	     *
84	     * @param region the canonical region (e.g. {@code "NSW"}, may be {@code null})
85	     * @return the IANA timezone name, or {@code null} when the region is not in the table
86	     */
87	    public static String timezoneForRegion(String region) {
88	        return REGION_TIMEZONE.get(region);
89	    }
90	
91	    /**
92	     * Whether the given 4-digit postcode is permitted for the given city. A city whose
93	     * region has a pinned postcode range accepts only postcodes within that (inclusive)
94	     * range; a city with no known region accepts any postcode.
95	     *
96	     * @param city     the owner's city (may be {@code null})
97	     * @param postcode the numeric value of a 4-digit postcode
98	     * @return {@code true} when the postcode is allowed for the city's region
99	     */
100	    public static boolean postcodeAllowedForCity(String city, int postcode) {
101	        int[] range = REGION_POSTCODES.get(regionFor(city));
102	        return range == null || (postcode >= range[0] && postcode <= range[1]);
103	    }
104	}
