18	    public static int luhn(String code) {
19	        int sum = 0;
20	        boolean dbl = true;
21	        for (int i = code.length() - 1; i >= 0; i--) {
22	            char c = code.charAt(i);
23	            if (c < '0' || c > '9') {
24	                continue;
25	            }
26	            int d = c - '0';
27	            if (dbl) {
28	                d *= 2;
29	                if (d > 9) {
30	                    d -= 9;
31	                }
32	            }
33	            sum += d;
34	            dbl = !dbl;
35	        }
36	        return (10 - (sum % 10)) % 10;
37	    }
