3	/**
4	 * The single definition of the American Soundex phonetic code of a name: an upper-case
5	 * letter followed by three digits (e.g. {@code Robert -> R163}). Names that sound alike map
6	 * to the same code, so it is the basis for household soft-matching on surname and forms the
7	 * surname component of an owner's {@link OwnerIdentity identity key}.
8	 */
9	public final class Soundex {
10	
11	    private Soundex() {
12	    }
13	
14	    /**
15	     * The four-character Soundex code of {@code value}: its first letter (upper-cased) followed
16	     * by three digits derived from the remaining consonants, right-padded with zeros. Non-letter
17	     * characters are ignored; a null or letter-free value yields the empty string.
18	     */
19	    public static String encode(String value) {
20	        if (value == null) {
21	            return "";
22	        }
23	        StringBuilder letters = new StringBuilder();
24	        for (int i = 0; i < value.length(); i++) {
25	            char c = value.charAt(i);
26	            if (Character.isLetter(c)) {
27	                letters.append(Character.toUpperCase(c));
28	            }
29	        }
30	        if (letters.length() == 0) {
31	            return "";
32	        }
33	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
34	        char previous = digit(letters.charAt(0));
35	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
36	            char letter = letters.charAt(i);
37	            char digit = digit(letter);
38	            if (digit == '0') {
39	                // 'h' and 'w' are transparent (do not reset the previous digit); a true vowel does.
40	                if (letter != 'H' && letter != 'W') {
41	                    previous = '0';
42	                }
43	                continue;
44	            }
45	            if (digit != previous) {
46	                code.append(digit);
47	            }
48	            previous = digit;
49	        }
50	        while (code.length() < 4) {
51	            code.append('0');
52	        }
53	        return code.toString();
54	    }
55	
56	    /** The Soundex digit for a consonant, or {@code '0'} for a vowel, 'h', 'w' or 'y'. */
57	    private static char digit(char letter) {
58	        switch (letter) {
59	            case 'B': case 'F': case 'P': case 'V':
60	                return '1';
61	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
62	                return '2';
63	            case 'D': case 'T':
64	                return '3';
65	            case 'L':
66	                return '4';
67	            case 'M': case 'N':
68	                return '5';
69	            case 'R':
70	                return '6';
71	            default:
72	                return '0';
73	        }
74	    }
75	}
