package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.audit.AuditEventSequence;
import org.springframework.samples.petclinic.rest.audit.OwnerCreatedEvent;

import tools.jackson.databind.ObjectMapper;

/**
 * Emits the audit trail for a successful owner create. Runs after {@link SaveOwner} has
 * assigned the owner's id, logging to the dedicated {@code AUDIT} logger both a human-readable
 * audit line and an immutable {@link OwnerCreatedEvent} serialized as JSON.
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    public void service(@Val Owner owner, OwnerMapper ownerMapper, AuditEventSequence sequence,
            ObjectMapper objectMapper) {
        int membershipLevel = ownerMapper.membershipLevel(owner);
        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                membershipLevel, ownerMapper.membershipNumber(owner));
        OwnerCreatedEvent event = OwnerCreatedEvent.of(sequence.next(), owner, membershipLevel);
        AUDIT.info(objectMapper.writeValueAsString(event));
    }
}

package org.springframework.samples.petclinic.model;

/**
 * The single definition of the <em>Luhn check digit</em> computed over the digits of a
 * customer code. Non-digit characters (separators, letters) are ignored; the remaining
 * digits are folded right-to-left with the rightmost digit doubled, and the check digit is
 * the amount that rounds the running sum up to the next multiple of ten.
 *
 * <p>Returned by the response mapper alongside the customer code so a caller can verify the
 * code was transcribed correctly.
 */
public final class CheckDigit {

    private CheckDigit() {
    }

    /** The Luhn check digit (0-9) over the digit characters of {@code code}. */
    public static int luhn(String code) {
        int sum = 0;
        boolean dbl = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }
}

