package org.springframework.samples.petclinic.model;

import java.time.LocalDate;
import java.time.Month;

/**
 * The single definition of the <em>fiscal year</em> a date falls in, where the fiscal year starts
 * on 1 July and is named by the calendar year it ends in — so 1 July 2025 to 30 June 2026 is fiscal
 * year 2026, labelled {@code FY26}.
 *
 * <p>Used by the response mapper to derive an owner's {@code fiscalYear} label and the year segment
 * of their membership number, and by {@link Tenure} to count elapsed fiscal years — all from the
 * business-day-adjusted registration date stamped on the owner at creation.
 */
public final class FiscalYear {

    /** The month a fiscal year starts on. */
    private static final Month START = Month.JULY;

    private FiscalYear() {
    }

    /** The fiscal year (named by the calendar year it ends in) that contains {@code date}. */
    public static int of(LocalDate date) {
        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
    }

    /** The {@code FY<YY>} label for the fiscal year containing {@code date}, where YY is the last
     * two digits of the fiscal year, or null when the date is unknown. */
    public static String label(LocalDate date) {
        return date == null ? null : String.format("FY%02d", of(date) % 100);
    }
}

package org.springframework.samples.petclinic.model;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * The single definition of a SHA-256 fingerprint of a string. Shared by everything that
 * fingerprints owner data — the customer code hash and household id (a truncated upper-case
 * prefix) and the identity key (the full lower-case digest) — so they all hash identically.
 */
public final class Sha256 {

    private Sha256() {
    }

    /**
     * The first {@code length} upper-case hex characters of SHA-256 over the UTF-8 bytes of
     * {@code value}.
     *
     * @param value  the string to hash
     * @param length the number of leading hex characters to return
     * @return the truncated upper-case hex digest
     */
    public static String upperHex(String value, int length) {
        return hex(value, "%02X").substring(0, length);
    }

    /**
     * The full 64-character lower-case hex SHA-256 over the UTF-8 bytes of {@code value}.
     *
     * @param value the string to hash
     * @return the complete lower-case hex digest
     */
    public static String lowerHex(String value) {
        return hex(value, "%02x");
    }

    private static String hex(String value, String byteFormat) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format(byteFormat, b & 0xFF));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required to derive a fingerprint", ex);
        }
    }
}

